$('#sensitivity').onclick=()=>{state.sensitivity=state.sensitivity>=1.5?.7:state.sensitivity+.2;$('#sensitivity').textContent=state.sensitivity.toFixed(1)+'×'};$('#cancel').onclick=closePanel}
function nearest(){let best=null,dist=2.8;scene.traverse(o=>{if(!o.userData.kind||['car','bike'].includes(o.userData.kind)&&o!==ride)return;const d=player.position.distanceTo(o.getWorldPosition(new THREE.Vector3()));if(d<dist){best=o;dist=d}});return best}
function frame(){const dt=Math.min(clock.getDelta(),.05);if(started&&!paused){state.hunger=clamp(state.hunger-dt*.045);state.thirst=clamp(state.thirst-dt*.065);state.fatigue=clamp(state.fatigue+dt*.025);if(state.hunger<8||state.thirst<8)state.health=clamp(state.health-dt*.35);if(Math.floor(clock.elapsedTime)%8===0&&Math.floor(clock.elapsedTime)!==frame.lastTick){frame.lastTick=Math.floor(clock.elapsedTime);updateHud()}
if(vehicleMode){const speed=vehicleMode==='bike'?13:10;const steer=(keys.a||keys.arrowleft?1:0)-(keys.d||keys.arrowright?1:0);ride.rotation.y+=steer*dt*1.6;const forward=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0);ride.position.x+=Math.sin(ride.rotation.y)*forward*speed*dt;ride.position.z+=Math.cos(ride.rotation.y)*forward*speed*dt;if(ride.position.x>80||ride.position.x< -80||ride.position.z< -130||ride.position.z>60){ride.position.x=clamp(ride.position.x,-80,80);ride.position.z=clamp(ride.position.z,-130,60)}player.position.set(ride.position.x,0,ride.position.z);player.visible=false;}
else{const f=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),s=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);if(f||s){const ang=Math.atan2(s,f);player.rotation.y=ang;const speed=keys.shift?7.4:4.7;player.position.x+=Math.sin(ang)*speed*dt;player.position.z+=Math.cos(ang)*speed*dt;player.position.x=clamp(player.position.x,-90,90);player.position.z=clamp(player.position.z,-140,80)}player.visible=true;}
const focus=vehicleMode?ride:player;const behind=new THREE.Vector3(Math.sin(focus.rotation.y)*8,4.2,Math.cos(focus.rotation.y)*8);const desired=focus.position.clone().add(behind);camera.position.lerp(desired,1-Math.pow(.002,dt));camera.lookAt(focus.position.x,1.1,focus.position.z);near=vehicleMode?null:nearest();if(near){$('#hint').style.display='block';$('#hintText').textContent=near.userData.label||({bed:'Sleep & save',shower:'Take a shower',fridge:'Make a meal',stove:'Make a meal',car:state.installed?'Drive car':'Inspect car',bike:'Ride motorbike',battery:'Pick up battery',wheel:'Pick up spare tyre',shop:'Browse car parts',grocery:'Visit grocery shop',bathroom:'Washroom'}[near.userData.kind]||'Interact')}else $('#hint').style.display='none';}
