cat > /tmp/opencode/test-game.mjs <<'EOF'
import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const errors = []
try {
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
  page.on('pageerror', e => errors.push(e.message))
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  if (await page.locator('#touch').isVisible()) throw new Error('Touch controls should be hidden in the menu')
  await page.locator('#settingsBtn').click()
  await page.locator('#quality').click()
  await page.locator('#sensitivity').click()
  await page.locator('#cancel').click()
  await page.locator('#newGame').click()
  if (!(await page.locator('#touch').isVisible())) throw new Error('Touch controls should appear during mobile gameplay')
  await page.keyboard.down('a')
  await page.waitForTimeout(800)
  await page.keyboard.up('a')
  const hint = await page.locator('#hintText').textContent()
  if (hint !== 'Bed') throw new Error(`Expected Bed interaction after walking, got ${hint}`)
  await page.keyboard.press('e')
  await page.locator('#sleep').click()
  const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('springSave')))
  if (!saved || saved.day !== 2) throw new Error('Sleep did not save day 2')
  await page.reload({ waitUntil: 'load' })
  await page.locator('#continue').click()
  if (!await page.locator('#topbar').isVisible()) throw new Error('Continue did not start saved game')
  if (errors.length) throw new Error(errors.join('; '))
  console.log('PASS: mobile controls, settings, movement/interactions, sleeping/save, continue, no page errors')
} finally { await browser.close() }
EOF
node /tmp/opencode/test-game.mjs
